<div x-show="isLeader && (requests.length || incomingBids.length)" class="border-t pt-6"><h3 class="font-medium mb-4">Permintaan Gabung (<span x-text="requests.length + incomingBids.length"></span>)</h3><div class="space-y-3"><template x-for="request in requests" :key="request.id"><div class="p-4 border rounded-lg bg-muted/30 flex flex-wrap items-start justify-between gap-3"><div><p class="font-medium" x-text="person(request.requester)"></p><p class="text-sm text-muted-foreground" x-text="email(request.requester)"></p><p class="text-sm mt-2 italic" x-text="request.message"></p></div><div class="flex gap-2"><x-btn size="sm" style="outline" @click="answer(request,false)" x-bind:disabled="saving">Tolak</x-btn><x-btn size="sm" @click="answer(request,true)" x-bind:disabled="saving">Terima</x-btn></div></div></template><template x-for="bid in incomingBids" :key="'bid-'+bid.id"><div class="p-4 border rounded-lg bg-muted/30 flex flex-wrap items-start justify-between gap-3"><div><p class="font-medium" x-text="(bid.group?.members || []).map(m=>person(m.student)).join(', ')"></p><p class="text-sm text-muted-foreground"><span x-text="bid.group?.members?.length || 0"></span> anggota &bull; <span x-text="bid.title?.title"></span></p></div><div class="flex gap-2"><x-btn size="sm" style="outline" @click="answerBid(bid,false)" x-bind:disabled="saving">Tolak</x-btn><x-btn size="sm" @click="answerBid(bid,true)" x-bind:disabled="saving">Terima</x-btn></div></div></template></div></div>
